    try {
      await unlink(temporaryPath);
    } catch {}
    throw error;
  }
}

interface ParsedArguments {
  options: Map<string, string>;
  positionals: string[];
}

function parseArguments(args: string[], allowed: ReadonlySet<string>): ParsedArguments {
  const options = new Map<string, string>();
